import sys

def valid(s):
    n = len(s)
    i = 0
    depth = 0
    want_operand = True
    while i < n:
        c = s[i]
        if want_operand:
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                i = j
                want_operand = False
                continue
            if c == '(':
                depth += 1
                i += 1
                continue
            return False
        else:
            if c in '+-*/':
                want_operand = True
                i += 1
                continue
            if c == ')':
                depth -= 1
                if depth < 0:
                    return False
                i += 1
                continue
            return False
    return (not want_operand) and depth == 0

def evaluate(s):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    nums = []
    ops = []
    bad = [False]

    def apply():
        op = ops.pop()
        b = nums.pop()
        a = nums.pop()
        if op == '+':
            nums.append(a + b)
        elif op == '-':
            nums.append(a - b)
        elif op == '*':
            nums.append(a * b)
        else:
            if b == 0:
                bad[0] = True
                nums.append(0)
            else:
                q = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    q = -q
                nums.append(q)

    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            nums.append(int(s[i:j]))
            i = j
            continue
        if c == '(':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
        else:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                apply()
            ops.append(c)
        i += 1
    while ops:
        apply()
    if bad[0]:
        return None
    return nums[0]

def main():
    s = sys.stdin.read().strip()
    if not valid(s):
        print('INVALID')
        return
    v = evaluate(s)
    print('INVALID' if v is None else v)

main()

