pos = 0

def peek():
    return s[pos] if pos < len(s) else ''

def expr():
    global pos
    v = term()
    while peek() in ('+', '-'):
        op = s[pos]
        pos += 1
        r = term()
        v = v + r if op == '+' else v - r
    return v

def term():
    global pos
    v = factor()
    while peek() in ('*', '/'):
        op = s[pos]
        pos += 1
        r = factor()
        if op == '*':
            v = v * r
        else:
            if r == 0:
                raise Bad()
            q = abs(v) // abs(r)
            v = -q if (v < 0) != (r < 0) else q
    return v

def factor():
    global pos
    c = peek()
    if c == '(':
        pos += 1
        v = expr()
        if peek() != ')':
            raise Bad()
        pos += 1
        return v
