    LIM = 10**15

    def num(maxd):
        return rng.randint(0, 10**rng.randint(1, maxd) - 1)

    def build(budget, depth, maxd, ops):
        # returns (string, value) with |value| and all intermediates well below 10^18
        if budget < 4 or depth == 0:
            v = num(maxd)
            return str(v), v
        nterms = rng.randint(1, 4)
        total_s = ''
        total_v = 0
        for ti in range(nterms):
            # term: factors joined by * or /
            nf = rng.choice([1, 1, 2, 3])
            ts = ''
            tv = 0
            for fi in range(nf):
                if rng.random() < 0.3 and budget > 8:
                    fs, fv = build(budget // (nterms * nf + 1), depth - 1, maxd, ops)
                    if not fs.isdigit():
                        fs = '(' + fs + ')'
                else:
                    fv = num(maxd)
                    fs = str(fv)
                if fi == 0:
                    ts, tv = fs, fv
                else:
                    op = rng.choice([o for o in '*/' if o in ops] or ['*'])
                    if op == '/' and fv == 0:
                        op = '*'
                    if op == '*' and abs(tv * fv) > LIM:
                        if fv != 0 and '/' in ops:
                            op = '/'
                        else:
                            continue
                    if op == '*':
                        tv = tv * fv
                    else:
                        q = abs(tv) // abs(fv)
                        tv = -q if (tv < 0) != (fv < 0) else q
                    ts += op + fs
            if ti == 0:
                total_s, total_v = ts, tv
            else:
                op = rng.choice('+-')
                total_v = total_v + tv if op == '+' else total_v - tv
                total_s += op + ts
        return total_s, total_v

    def valid_like(maxd=3, ops='+-*/', budget=30, depth=3):
