        while i < n:
            c = s[i]
            if want:
                if c.isdigit():
                    while i < n and s[i].isdigit():
                        i += 1
                    want = False
                    continue
                if c == '(':
                    depth += 1; i += 1; continue
                return False
            else:
                if c in '+-*/':
                    want = True; i += 1; continue
                if c == ')':
                    depth -= 1
                    if depth < 0:
                        return False
                    i += 1; continue
                return False
        return (not want) and depth == 0

