            if t and not is_valid(t) and ' ' not in t and 'x' not in t and '.' not in t:
                return t
        return s + '+'

    def flat(nterms, ops='+-*/'):
        parts = []
        for ti in range(nterms):
            cur = rng.randint(1, 9)
            ts = str(cur)
            for _ in range(rng.randint(0, 3)):
                op = rng.choice([o for o in '*/' if o in ops] or ['*'])
                n2 = rng.randint(1, 9)
                if op == '*':
                    if abs(cur * n2) > 10**9:
