                    cur = cur * n2
                else:
                    q = abs(cur) // n2
                    cur = q
                ts += op + str(n2)
            parts.append(ts)
        s = parts[0]
        for p in parts[1:]:
            s += rng.choice('+-') + p
        return s

    def deep_left(d):
        cur = rng.randint(1, 9)
        s = '(' * d + str(cur)
        for _ in range(d):
            n2 = rng.randint(1, 9)
            op = rng.choice('+-*') if abs(cur) < 10**11 else rng.choice('+-')
            s += ')' + op + str(n2)
            cur = cur + n2 if op == '+' else cur - n2 if op == '-' else cur * n2
        return s

    def deep_right(d):
        nums = [rng.randint(1, 9) for _ in range(d + 1)]
        ops = [rng.choice('+-') for _ in range(d)]
        s = ''
        for i in range(d):
            s += str(nums[i]) + ops[i] + '('
